// ── Library map — a standard is seedable only when it has an entry here ──────
const CLAUSE_LIBRARIES = {
  brcgs_packaging: { issue: '7',    clauses: BRCGS_PACKAGING_CLAUSES },
  iso_9001:        { issue: '2015', clauses: ISO_9001_CLAUSES },
  iso_14001:       { issue: '2015', clauses: ISO_14001_CLAUSES },
  iso_45001:       { issue: '2018', clauses: ISO_45001_CLAUSES },
};

Deno.serve(async (req) => {
  const base44 = createClientFromRequest(req);
  const user = await base44.auth.me();

  if (!user || user.role !== 'admin') {
    return Response.json({ error: 'Forbidden: Admin access required' }, { status: 403 });
  }

  const body = await req.json().catch(() => ({}));
  const standard = body.standard || 'brcgs_packaging';

  const library = CLAUSE_LIBRARIES[standard];
  if (!library) {
    return Response.json({
      success: false,
      message: `No clause library exists for ${standard} yet. Available: ${Object.keys(CLAUSE_LIBRARIES).join(', ')}.`,
    }, { status: 422 });
  }
  const issue_number = body.issue_number || library.issue;

  // Idempotency check — don't seed if clauses already exist for this standard
  const existing = await base44.asServiceRole.entities.BRCClause.filter({ standard }, '-created_date', 1);
  if (existing.length > 0) {
    return Response.json({
      success: false,
      message: `Clauses for ${standard} already exist (${existing.length}+ records). Use force:true to re-seed.`,
      count: existing.length,
    });
  }

  // Force re-seed if requested
  if (body.force) {
    const allExisting = await base44.asServiceRole.entities.BRCClause.filter({ standard }, 'display_order', 500);
    for (const c of allExisting) {
      await base44.asServiceRole.entities.BRCClause.delete(c.id);
    }
  }

  // Bulk create
  const records = library.clauses.map(c => ({
    ...c,
    standard,
    issue_number,
  }));

  // Create in batches of 10
  const results = [];
  for (let i = 0; i < records.length; i += 10) {
    const batch = records.slice(i, i + 10);
    const created = await base44.asServiceRole.entities.BRCClause.bulkCreate(batch);
    results.push(...created);
  }

  return Response.json({
    success: true,
    standard,
    issue_number,
    seeded: results.length,
    message: `Successfully seeded ${results.length} clauses for ${standard} (${issue_number}).`,
  });
});